pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {NewIntelTechMedia} from "../src/NewIntelTechMedia.sol";

contract InvMutTest is Test {
    NewIntelTechMedia c;
    function setUp() public { c = new NewIntelTechMedia(); }
    function testRegression_property() public {
        address user = address(0x123);
        vm.prank(user);
        try c.NETM() {
            bool ok = true;
            assertTrue(ok == false, "Bug: function should have reverted in reference");
        } catch {
            assertTrue(true, "Reference: function reverted as expected");
        }
    }
}
